head.script:
scwin.test = function() {
    $w.log("main" + "_initScript");
}
scwin.test2 = function() {
    $w.log("main" + "_initScript2");
}
scwin.post1 = function() {
    $w.log("main" + "_postScript1");
}
scwin.post2 = function() {
    $w.log("main" + "_postScript2");
}
scwin.onpageload = function() {
    $w.log("main" + "_onpageload");
    if (console.log) {
        console.log("main" + "_onpageload");
    }
}
scwin.checkLog = function() {
    if (WebSquare.logger.getErrorLog()) {
        return false;
    }
    return true;
}
scwin.checkChart = function(cl) {
    if (document.getElementsByClassName(cl).length > 0) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 상단의 'setChartColumnRef'버튼을 클릭한다.
    //1. After executing the main sample, click the 'setChartColumnRef' button at the top.
    //Verify step 1. FusionChart is updated.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('w2_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkChart('raphael-group-9-parentgroup')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
